import {View, Text, TouchableOpacity} from 'react-native';
import React, {useEffect, useState} from 'react';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {Language} from '../..';
import { IconCheckedRadio, IconEngland, IconRadio, IconVietNam } from '../../../../assets/images';
import TextCM from '../../../../components/Text';
import { View as ViewCM } from 'react-native';
import { SizeDP } from '../../../../constants/Size';
import ButtonCM from '../../../../components/Button';

type LanguageType = {
  title: string;
  type: Language;
  icon?: any;
};
type Props = {
  currentLanguage: string;
  onCancel: () => void;
  onConfirm: (value: string) => void;
};

const ChangeLanguage = ({currentLanguage, onCancel, onConfirm}: Props) => {
  const {t} = useTranslation();
  const [language, setLanguage] = useState<string>(currentLanguage);

  useEffect(() => {
    setLanguage(currentLanguage);
  }, [currentLanguage]);

  const LANGUAGES: LanguageType[] = [
    {
      title: t('ST.TxtVietName'),
      type: Language.VietNam,
      icon: <IconVietNam />,
    },
    {
      title: t('ST.TxtEnglish'),
      type: Language.English,
      icon: <IconEngland />,
    },
  ];

  const checkCurrentLanguage = (type: Language) => {
    return type === language;
  };

  const onPressLanguage = (type: Language) => {
    setLanguage(type);
  };

  const onPressConfirm = () => {
    onConfirm(language);
  };

  const renderItem = (item: LanguageType) => {
    return (
      <TouchableOpacity
        key={item.type}
        style={styles.viewItem}
        onPress={() => {
          onPressLanguage(item.type);
        }}>
        {checkCurrentLanguage(item.type) ? (
          <IconCheckedRadio width={SizeDP(24)} height={SizeDP(24)} />
        ) : (
          <IconRadio width={SizeDP(24)} height={SizeDP(24)} />
        )}
        {item.icon}
        <TextCM style={styles.txtItem}>{item.title}</TextCM>
      </TouchableOpacity>
    );
  };

  return (
    <ViewCM style={styles.container}>
      <TextCM style={styles.txtTitle}>{t('ST.TxtPicLanguage')}</TextCM>
      <ViewCM style={styles.viewBody}>{LANGUAGES.map(renderItem)}</ViewCM>
      <ViewCM style={styles.viewBtn}>
        <ButtonCM
          type="white"
          label={t('CM.BtnCancel')}
          onPress={onCancel}
          style={styles.btn}
        />
        <ButtonCM
          label={t('CM.BtnConfirm')}
          onPress={onPressConfirm}
          style={styles.btn}
        />
      </ViewCM>
    </ViewCM>
  );
};

export default ChangeLanguage;
