import {BASE_URL} from './httpClient';
export const AccountServices = (fetchRequest: any) => ({
  async postUpdateAvatar(body: any) {
    try {
      const endPoint = '/services/uaa/api/account/avatar';
      const res = await fetchRequest({
        url: `${BASE_URL}${endPoint}`,
        method: 'POST',
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        body,
      });
      return Promise.resolve(res.josn());
    } catch (error) {
      console.error('Error postUpdateAvatar:', error);
      return Promise.reject(error);
    }
  },
  async postUpdateInfo(body: any) {
    try {
      const endPoint = '/services/uaa/api/account';
      const res = await fetchRequest({
        url: `${BASE_URL}${endPoint}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body,
      });
      return Promise.resolve(res.josn());
    } catch (error) {
      console.error('Error postUpdateInfo:', error);
      return Promise.reject(error);
    }
  },
  async fetchTwoFactorState(email: string) {
    try {
      const endPoint = `services/uaa/api/user/is-active-two-factor/${email}`;
      const res = await fetchRequest({
        url: `${BASE_URL}/${endPoint}`,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(res);
    } catch (error) {
      console.error('Error fetchTwoFactorState:', error);
      return Promise.reject(error);
    }
  },
  async turnOffTwoFactor(body: any) {
    try {
      const endPoint = `services/uaa/api/p/user-secrect-codes/active-two-factor-app`;
      const res = await fetchRequest({
        url: `${BASE_URL}/${endPoint}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body,
      });
      return Promise.resolve(res.josn());
    } catch (error) {
      console.error('Error turnOffTwoFactor:', error);
      return Promise.reject(error);
    }
  },
});
