import {debounce, isEmpty} from 'lodash';
import React, {useEffect, useRef, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, RefreshControl, View} from 'react-native';
import DocumentItem from './components/DocumentItem';
import InputSearch from './components/InputSearch';
import ModalFilter from './components/ModalFilter';
import ModalSortOrganization from './components/ModalFilter/components/ModalSortOrganization';
import {dataFavorite, getNameTitle, getPathApi} from './helper';
import styles from './styles';
import {
  IDocument,
  IOrganization,
} from '../../../model/interface/envelope.interface';
import {ItemType} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import HeaderCM from '../../../components/Header/HeaderCM';
import TextCM from '../../../components/Text';
import {useDocumentStore} from '../../../navigation/SideMenu/store/app-store';
import {useDocumentServices} from '../../../hook/apiHook/useApi';
import DocumentTemplate from '../document-template';
import {useAppSelector} from '../../../hook/useRedux';

const DocumentScreen = () => {
  const {t} = useTranslation();
  const {currentFocused, isDueDateStatus, showSortOrganization} =
    useDocumentStore();
  const reloadData = useDocumentStore(state => state.reloadData);
  const isShowModalOrganization = useDocumentStore(
    state => state.isShowModalOrganization,
  );
  const currentFocusedOrganization = useDocumentStore(
    state => state.currentFocusOrganization,
  );

  const [searchText, setSearchText] = useState('');
  const [debouncedSearchText, setDebouncedSearchText] = useState('');
  const [data, setData] = useState<IDocument[] & IOrganization[]>([]);
  const [totalPage, setTotalPage] = useState(1);
  const [page, setPage] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isShowFilter, setIsShowFilter] = useState(false);
  const [filterData, setFilterData] = useState<any>({});

  const refFlatList = useRef<any>();
  const {dataAccount} = useAppSelector(state => state.account);

  const DocumentServices = useDocumentServices();

  const debouncedSearch = debounce((text: string) => {
    setDebouncedSearchText(text);
  }, 300);

  useEffect(() => {
    debouncedSearch(searchText);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchText]);

  useEffect(() => {
    if (currentFocused !== ItemType.Authen) {
      getData(0, debouncedSearchText, filterData);
    }
  }, [
    currentFocused,
    debouncedSearchText,
    filterData,
    reloadData,
    currentFocusedOrganization,
    isDueDateStatus,
  ]);

  useEffect(() => {
    if (currentFocused !== ItemType.Authen) {
      if (!isEmpty(filterData) || searchText) {
        resetData();
      }
      if (data.length > 0) {
        refFlatList.current?.scrollToOffset({animated: true, offset: 0});
      }
    }
  }, [currentFocused]);

  const resetData = () => {
    setSearchText('');
    setDebouncedSearchText('');
    setFilterData({});
  };

  const getData = async (
    page = 0,
    keyWord = '',
    filterData?: {sort: any; search: any; sort2?: string} | undefined,
  ) => {
    const pathApt = getPathApi(
      currentFocused,
      currentFocusedOrganization?.id,
      dataAccount.email,
      dataAccount.orgIn,
    );
    const params = {
      page,
      size: 10,
      search: JSON.stringify({
        ...pathApt.params.search,
        keyWord,
        ...filterData?.search,
        ...(isDueDateStatus ? {dueDateStatus: ['d', 'o']} : {}),
      }),
    };

    const data = await DocumentServices.getData(pathApt.path, params, {
      sort: filterData?.sort ? filterData.sort : pathApt.params.sort,
      sort2: filterData?.sort2,
      isDueDateStatus,
    });

    var newData = data.data;
    if (
      currentFocused !== ItemType.Draft &&
      currentFocused !== ItemType.Trash
    ) {
      const dataFavorites = isEmpty(newData)
        ? []
        : await DocumentServices.getEnvelopeFavourite(
            data.data.map((i: IDocument) => i.id),
          );
      newData = dataFavorite(newData, dataFavorites);
    }
    if (page) {
      setData(prev => [...prev, ...newData]);
    } else {
      setPage(0);
      setData(newData);
    }
    setTotalPage(data.totalPage);
    setIsRefreshing(false);
  };

  const renderItem = ({item}: {item: IDocument & IOrganization}) => {
    return <DocumentItem data={item} />;
  };

  const onEndReached = async () => {
    if (totalPage > 1 && page + 1 < totalPage) {
      getData(page + 1, debouncedSearchText, filterData);
      setPage(page + 1);
    }
  };

  const onRefresh = async () => {
    setIsRefreshing(true);
    getData(0, debouncedSearchText, filterData);
  };

  const toggleShowFilter = () => {
    setIsShowFilter(!isShowFilter);
  };

  const toggleShowSortOrganization = () => {
    showSortOrganization(false);
  };

  const onFilter = (data: any) => {
    setFilterData(data);
  };

  return (
    <View style={styles.ctnMain}>
      <HeaderCM
        title={getNameTitle(currentFocused, t)}
        // isShowIconLeft={false}
        // containerStyle={styles.header}
      />
      <InputSearch
        setSearchText={setSearchText}
        searchText={searchText}
        onPressFilter={toggleShowFilter}
      />
      <FlatList
        data={data}
        ref={refFlatList}
        keyExtractor={item => item.id}
        renderItem={renderItem}
        contentContainerStyle={styles.body}
        onEndReached={onEndReached}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
        }
        ListEmptyComponent={<Nodata />}
      />
      <ModalFilter
        onFilter={onFilter}
        isShowFilter={isShowFilter}
        toggleShowFilter={toggleShowFilter}
        filterData={filterData}
      />
      <ModalSortOrganization
        isShowFilter={isShowModalOrganization}
        toggleShowFilter={toggleShowSortOrganization}
      />
    </View>
  );
};

export default () => {
  const currentFocused = useDocumentStore(state => state.currentFocused);
  if (
    currentFocused === ItemType.MyDocumentTemplate ||
    currentFocused === ItemType.TemplateShare
  )
    return <DocumentTemplate />;
  return <DocumentScreen />;
};

const Nodata = () => {
  const {t} = useTranslation();
  return <TextCM style={styles.txtNoData}>{t('DC.TxtNoData')}</TextCM>;
};
