import React from 'react';
import {useTranslation} from 'react-i18next';
import {formatNumber} from './helper';
import styles from './styles';
import {TouchableOpacity, View} from 'react-native';
import {useNavigation} from '@react-navigation/native';
import TextCM from '../../../../components/Text';
import {NavigationName} from '../../../../constants';
import {IHomeScreen} from '../../interface';

type ItemType = {
  title: string;
  value: number;
  bgColor: string;
  textColor: string;
};

const OverviewDocument = ({dataHomeScreen}: {dataHomeScreen: IHomeScreen}) => {
  const navigation = useNavigation<any>();
  const {t} = useTranslation();

  const data = [
    {
      title: t('HM.TxtPending'),
      value: dataHomeScreen.pending,
      bgColor: '#ECEFFE',
      textColor: '#0673C6',
    },
    {
      title: t('HM.TxtWaitingResponse'),
      value: dataHomeScreen.waitingResponse,
      bgColor: '#FEF4E6',
      textColor: '#E18308',
    },
    {
      title: t('HM.TxtExpire'),
      value: dataHomeScreen.expire,
      bgColor: '#FEECEB',
      textColor: '#DA3E33',
    },
  ];

  const renderItem = (item: ItemType) => {
    return (
      <TouchableOpacity
        onPress={() => {
          onPressItem(item);
        }}
        key={item.title}
        style={[
          styles.viewItem,
          {
            backgroundColor: item.bgColor,
          },
        ]}>
        <TextCM
          style={[
            styles.txtValue,
            {
              color: item.textColor,
            },
          ]}>
          {formatNumber(item.value)}
        </TextCM>
        <TextCM
          style={[
            styles.txtName,
            {
              color: item.textColor,
            },
          ]}>
          {item.title}
        </TextCM>
      </TouchableOpacity>
    );
  };

  const onPressItem = (item: ItemType) => {
    switch (item.title) {
      case t('HM.TxtPending'):
        navigation.navigate(NavigationName.NotificationListScreen as never);
        break;
      case t('HM.TxtWaitingResponse'):
        // dispatch(documentActions.updateCurrentFocused(DocumentType.Inprogress));
        // dispatch(documentActions.updateIsDueDateStatus(false));
        navigation.navigate(NavigationName.DocumentScreen, {
          screen: NavigationName.DocumentListScreen,
        });
        break;
      case t('HM.TxtExpire'):
        // dispatch(documentActions.updateCurrentFocused(DocumentType.Inprogress));
        // dispatch(documentActions.updateIsDueDateStatus(true));
        navigation.navigate(NavigationName.DocumentScreen, {
          screen: NavigationName.DocumentListScreen,
        });
        break;
    }
  };

  return (
    <View style={styles.container}>
      <TextCM style={styles.txtTitle}>{t('HM.TxtOverviewDocument')}</TextCM>
      <View style={styles.viewBody}>{data.map(renderItem)}</View>
    </View>
  );
};

export default OverviewDocument;
