import {ItemType} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';

type PathRes = {
  path: string;
  params?: {sort: string};
};

export const getTitleTemplate = (type: ItemType) => {
  if (type === ItemType.TemplateShare) {
    return 'DC.TxtTemplateShare';
  }
  return 'DC.TxtDocumentTemplate';
};

export const getPathApi = (type?: string): PathRes => {
  if (type === ItemType.MyDocumentTemplate) {
    return {
      path: 'findbyowner',
      params: {sort: 'createdDate,desc'},
    };
  }
  return {
    path: 'shared',
  };
};
