import React, {
  useEffect,
  useCallback,
  useState,
  memo,
  useMemo,
  useRef,
} from 'react';
import {useTranslation} from 'react-i18next';
import styles from './styles';
import PicTypeView from './components/PicTypeView';
import PicDateView from './components/PicDateView';
import SortDateView from './components/SortDateView';
import {isEmpty} from 'lodash';
import {getDataType} from './components/PicTypeView/helper';
import {TextInput, View} from 'react-native';
import {GroupData} from '../../../../../components/GroupRadio';
import {DateUtils} from '../../../../../utils';
import TextCM from '../../../../../components/Text';
import {
  ItemType,
  MainItemType,
} from '../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import TextField from '../../../../../components/TextField';
import ButtonCM from '../../../../../components/Button';
import BottomSheetCM from '../../../../../components/BottomSheet';
import {useDocumentStore} from '../../../../../navigation/SideMenu/store/app-store';

type Props = {
  toggleShowFilter: () => void;
  isShowFilter: boolean;
  onFilter: (data: any) => void;
  filterData: DataSearch;
};

type DataSearch = {
  search: {
    from?: string | Date | null;
    to?: string | Date | null;
    field?: string;
    owner?: string;
  };
  sort: string | number;
  sort2?: string;
};

const ModalFilter = ({
  toggleShowFilter,
  isShowFilter,
  onFilter,
  filterData,
}: Props) => {
  const {t} = useTranslation();
  const currentFocused = useDocumentStore(state => state.currentFocused);
  const mainCurrentFocused = useDocumentStore(
    state => state.mainCurrentFocused,
  );
  const [fromDate, setFromDate] = useState(null);
  const [toDate, setToDate] = useState(null);
  const [sortDate, setSortDate] = useState<GroupData | null>(null);
  const [picType, setPicType] = useState<any>(null);
  const [dataCreator, setDataCreator] = useState<string>('');
  const textInputRef = useRef<TextInput>(null);

  useEffect(() => {
    if (isEmpty(filterData)) {
      resetData();
    }
  }, [filterData]);

  const resetData = useCallback(() => {
    setFromDate(null);
    setToDate(null);
    setSortDate(null);
    setPicType(null);
    setDataCreator('');
  }, []);

  const onPressRemoveFilter = useCallback(() => {
    toggleShowFilter();
    onFilter(null);
  }, [toggleShowFilter, onFilter]);

  const onPressFilter = useCallback(() => {
    const dataSearch: DataSearch = {
      search: {},
      sort: sortDate?.id || 'createdDate,desc',
    };
    if (fromDate) {
      dataSearch.search.from = DateUtils.convertDateToStartDay(fromDate);
      dataSearch.search.field = picType?.id || 'createdDate';
    }
    if (toDate) {
      dataSearch.search.to = DateUtils.convertDateToEndDay(toDate);
      dataSearch.search.field = picType?.id || 'createdDate';
    }
    if (dataCreator) dataSearch.search.owner = dataCreator;

    let sort2 = '';
    if (
      (picType?.id === 'createdDate' &&
        !sortDate?.id.toString().includes('createdDate')) ||
      (picType?.id &&
        picType?.id !== 'createdDate' &&
        !sortDate?.id.toString().includes('createdDate') &&
        getDataType(currentFocused)?.some(i => i.id === 'createdDate')) ||
      (!picType?.id && !sortDate?.id.toString().includes('createdDate'))
    ) {
      sort2 = 'createdDate';
    }
    if (sort2) {
      dataSearch.sort2 = sort2;
    }

    toggleShowFilter();
    onFilter(dataSearch);
  }, [
    toggleShowFilter,
    onFilter,
    fromDate,
    toDate,
    picType,
    sortDate,
    dataCreator,
    currentFocused,
  ]);

  const onChangeFromDate = useCallback((date: any) => {
    setFromDate(date);
  }, []);

  const onChangeToDate = useCallback((date: any) => {
    setToDate(date);
  }, []);

  const onChangeDataCreator = useCallback((text: string) => {
    setDataCreator(text);
  }, []);
  const onDismissKeyboard = () => {
    if (textInputRef.current) {
      textInputRef.current.blur();
    }
  };

  const MemoizedPicTypeView = useMemo(() => memo(PicTypeView), [picType]);
  const MemoizedPicDateView = useMemo(() => memo(PicDateView), [fromDate]);
  const MemoizedSortDateView = useMemo(() => memo(SortDateView), [toDate]);

  const Content = useMemo(() => {
    return (
      <View style={styles.container}>
        <View style={styles.viewDate}>
          <TextCM style={styles.txtTitle}>
            {t('DC.modal.TxtFilterByDate')}
          </TextCM>
          {mainCurrentFocused === MainItemType.MainDocumentOrganization && (
            <TextField
              ref={textInputRef}
              value={dataCreator}
              label={t('DC.CreatedEmail')}
              placeholder={t('DC.EnterTheEmail')}
              onChangeText={onChangeDataCreator}
            />
          )}
          {currentFocused !== ItemType.Draft && (
            <MemoizedPicTypeView
              value={picType}
              onPicType={setPicType}
              onDismissKeyboard={onDismissKeyboard}
            />
          )}
          <View style={styles.viewPicDate}>
            <MemoizedPicDateView
              label={t('DC.modal.TxtFromDate')}
              date={fromDate}
              maxDate={toDate}
              onChangeDate={onChangeFromDate}
            />
            <MemoizedPicDateView
              label={t('DC.modal.TxtToDate')}
              date={toDate}
              minDate={fromDate}
              onChangeDate={onChangeToDate}
            />
          </View>
          <MemoizedSortDateView
            data={sortDate as GroupData}
            onChangeSortDate={setSortDate}
          />
        </View>
        <View style={styles.footer}>
          <ButtonCM
            label={t('DC.modal.BtnRemoveFilter')}
            type="white"
            onPress={onPressRemoveFilter}
            style={styles.btnFooter}
          />
          <ButtonCM
            label={t('DC.modal.BtnFilter')}
            onPress={onPressFilter}
            style={styles.btnFooter}
          />
        </View>
      </View>
    );
  }, [
    t,
    mainCurrentFocused,
    dataCreator,
    onChangeDataCreator,
    currentFocused,
    picType,
    setPicType,
    fromDate,
    toDate,
    onChangeFromDate,
    onChangeToDate,
    sortDate,
    setSortDate,
    onPressRemoveFilter,
    onPressFilter,
  ]);

  return (
    <>
      <BottomSheetCM
        title={t('DC.modal.TxtFilter')}
        renderContent={Content}
        onClose={toggleShowFilter}
        isVisible={isShowFilter}
      />
    </>
  );
};

export default memo(ModalFilter);
