import {isArray, isEmpty, isUndefined} from 'lodash';
import React, {useEffect, useRef, useState} from 'react';
import {ScrollView, useWindowDimensions, View} from 'react-native';
import Svg, {Line} from 'react-native-svg';

import BlockComponent from '../BlockComponent';
import styles from './styles';
import {ReactNativeZoomableView} from '@openspacelabs/react-native-zoomable-view';
import ItemRowView from '../ItemRowView';
import {IParties} from '../../../../../../../model/interface/envelope.interface';
import {
  convertHistoryStatus,
  DocumentStatus,
  mappingBGColorHistoryStatus,
  mappingColorHistoryStatus,
} from '../../../../../helper';
import {
  IconEllipse,
  IconEllipseInprogress,
  IconEllipseReject,
  IconEllipseSuccess,
  IconGreyCirclePlus,
  IconGreyDown,
} from '../../../../../../../assets/images';

type Props = {
  data: IParties[];
  status: DocumentStatus;
};

type ConvertedData = {
  role: string;
  label: string;
  color: string;
  bgColor: string;
  partyId: string;
}[][];

const WorkflowDiagram = ({data, status}: Props) => {
  const {width: ScreenWidth, height: ScreenHeight} = useWindowDimensions();
  const refZoomView = useRef<ReactNativeZoomableView>(null);
  const [widthView, setWidthView] = useState(Math.round(ScreenWidth));
  const [widthRowData, setWidthRowData] = useState<any>([]);
  const [heightRowData, setHeightRowData] = useState<any>([]);

  const groupByOrder = (input: any) => {
    const result: any[] = [];
    const orderMap = new Map();

    input
      .sort((a: any, b: any) => a?.order - b?.order)
      .forEach((item: any) => {
        if (!orderMap.has(item.order)) {
          orderMap.set(item.order, []);
        }
        orderMap.get(item.order).push(item);
      });

    orderMap.forEach((value, key) => {
      if (value.length === 1) {
        result.push(value[0]);
      } else {
        result.push(value);
      }
    });

    return result;
  };

  const convertData = (data: any) => {
    return data.map((item: any) => {
      if (isArray(item)) {
        return convertData(item);
      }
      const listRoleReview = item.recipients
        ?.sort((a: any, b: any) => a?.order - b?.order)
        ?.filter((i: any) => i.role === 'reviewer')
        .map((i: any) => ({
          role: i.role,
          label: i.contact.name,
          color: mappingColorHistoryStatus(
            convertHistoryStatus(i.status, i.role),
          ),
          bgColor: mappingBGColorHistoryStatus(
            convertHistoryStatus(i.status, i.role),
          ),
          partyId: i.partyId,
          order: i.order,
        }));

      const listRoleOther = item.recipients
        ?.sort((a: any, b: any) => a?.order - b?.order)
        .filter((i: any) => i.role !== 'reviewer')
        .map((i: any) => ({
          role: i.role,
          label: i.contact.name,
          color: mappingColorHistoryStatus(
            convertHistoryStatus(i.status, i.role),
          ),
          bgColor: mappingBGColorHistoryStatus(
            convertHistoryStatus(i.status, i.role),
          ),
          partyId: i.partyId,
          order: i.order,
        }));
      return [...listRoleReview, ...listRoleOther];
    });
  };

  const groupByOrderAndRole = (input: any) => {
    const result: any[] = [];
    const orderRoleMap = new Map();

    input.forEach((item: any) => {
      const key = `${item.order}-${item.role}`;
      if (!orderRoleMap.has(key)) {
        orderRoleMap.set(key, []);
      }
      orderRoleMap.get(key).push(item);
    });

    orderRoleMap.forEach((value, key) => {
      if (value.length === 1) {
        result.push(value[0]);
      } else {
        result.push(value);
      }
    });
    return result;
  };

  const dataRender2: ConvertedData = convertData(groupByOrder(data));

  const renderRowData = (item: any, index?: number) => {
    const newData: ConvertedData = groupByOrderAndRole(item);
    const currentHeight = !isUndefined(index) ? heightRowData?.[index] || 0 : 0;
    const maxHeight =
      (!isEmpty(heightRowData) ? Math.max(...heightRowData) : 0) || 0;

    return (
      <View
        key={index}
        style={{
          justifyContent: 'center',
          alignItems: 'center',
          ...styles.viewStyleCtn,
          marginHorizontal: 10,
          gap: 24,
        }}
        onLayout={event => {
          if (!isUndefined(index)) {
            const {width, height} = event.nativeEvent.layout;
            const newRowData = [...widthRowData];
            const newHeightRowData = [...heightRowData];
            newRowData[index] = width;
            newHeightRowData[index] = height;
            setWidthRowData([...newRowData]);
            setHeightRowData([...newHeightRowData]);
          }
        }}>
        {newData.map((i: any, j: number) => {
          if (!isArray(i)) {
            return (
              <View key={j} style={{}}>
                <BlockComponent
                  data={i}
                  showLineDown={j !== newData.length - 1}
                />
              </View>
            );
          }
          return (
            <ItemRowView data={i} key={j} isLast={j === newData.length - 1} />
          );
        })}
        {!isUndefined(index) && (
          <Svg
            height={24 + (maxHeight - currentHeight) / 2}
            width="100%"
            style={{
              top: -(22 + (maxHeight - currentHeight) / 2),
              left: 12.5,
              position: 'absolute',
            }}>
            <Line
              x1="50%"
              y1="0"
              x2="50%"
              y2="100"
              stroke="#D0D5DD"
              strokeWidth="2"
              strokeDasharray="4"
            />
          </Svg>
        )}
        <View
          style={{
            top: -8,
            left: 0,
            right: 0,
            alignItems: 'center',
            position: 'absolute',
          }}>
          <IconGreyDown width={10} height={14} />
        </View>
        {!isUndefined(index) && (
          <Svg
            height={24 + (maxHeight - currentHeight) / 2}
            width="100%"
            style={{
              bottom: -(24 + (maxHeight - currentHeight) / 2),
              left: 12.5,
              position: 'absolute',
            }}>
            <Line
              x1="50%"
              y1="0"
              x2="50%"
              y2="100"
              stroke="#D0D5DD"
              strokeWidth="2"
              strokeDasharray="4"
            />
          </Svg>
        )}
        {/* dấu cộng dưới*/}
      </View>
    );
  };

  const checkPartyId = (item: any) => {
    return (
      item.length > 1 &&
      item.every((i: any) => !isArray(i)) &&
      item.every((i: any) => i.role === item[0].role)
    );
  };

  const getWidth = () => {
    if (isEmpty(widthRowData)) return 0;
    let numberRow = 1;
    dataRender2.forEach(item => {
      if (item.length > numberRow) {
        numberRow = item.length;
      }
    });
    return (
      widthRowData.reduce((a: number, b: number) => a + b, 0) -
      (widthRowData[0] / 2 + widthRowData[widthRowData.length - 1] / 2) +
      (numberRow - 1) * 20
    );
  };

  const renderGroupData = (item: any) => {
    const data = groupByOrder(item);

    return (
      <View
        style={{
          paddingVertical: 12,
          gap: 24,
        }}>
        {data.map((item: any, index: number) => {
          if (isArray(item))
            return (
              <View
                key={index}
                style={{
                  flexDirection: 'row',
                  gap: 42,
                  alignItems: 'center',
                  paddingVertical: data.some(i => !isArray(i)) ? 24 : 24,
                }}>
                {item.map((i: any, j: number) => {
                  return (
                    <View key={j} style={styles.workflowItem}>
                      <BlockComponent data={i} />
                      <Svg
                        height="24"
                        width="100%"
                        style={{
                          top: -24,
                          left: 0,
                          position: 'absolute',
                        }}>
                        <Line
                          x1="50%"
                          y1="0"
                          x2="50%"
                          y2="100"
                          stroke="#D0D5DD"
                          strokeWidth="2"
                          strokeDasharray="4"
                        />
                      </Svg>
                      <Svg
                        height="24"
                        width="100%"
                        style={{
                          bottom: -24,
                          left: 0,
                          position: 'absolute',
                        }}>
                        <Line
                          x1="50%"
                          y1="0"
                          x2="50%"
                          y2="100"
                          stroke="#D0D5DD"
                          strokeWidth="2"
                          strokeDasharray="4"
                        />
                      </Svg>
                    </View>
                  );
                })}
                <>
                  {/* Gạch ngang trên */}
                  <Svg
                    height="24"
                    width="100%"
                    style={{
                      top: -4,
                      left: 75,
                      position: 'absolute',
                    }}>
                    <Line
                      x1="0"
                      y1="2"
                      x2={(item.length - 1) * 150 + (item.length - 1) * 42}
                      y2="2"
                      stroke="#D0D5DD"
                      strokeWidth="2"
                      strokeDasharray="4"
                    />
                  </Svg>

                  {/* Gạch ngang dưới */}
                  <Svg
                    height="24"
                    width="100%"
                    style={{
                      bottom: -22,
                      left: 75,
                      position: 'absolute',
                    }}>
                    <Line
                      x1="0"
                      y1="2"
                      x2={(item.length - 1) * 150 + (item.length - 1) * 42}
                      y2="2"
                      stroke="#D0D5DD"
                      strokeWidth="2"
                      strokeDasharray="4"
                    />
                  </Svg>

                  <Svg
                    height="8"
                    width="100%"
                    style={{
                      top: -10,
                      left: 0,
                      position: 'absolute',
                    }}>
                    <Line
                      x1="50%"
                      y1="0"
                      x2="50%"
                      y2="100"
                      stroke="#D0D5DD"
                      strokeWidth="2"
                      strokeDasharray="4"
                    />
                  </Svg>

                  <Svg
                    height="8"
                    width="100%"
                    style={{
                      bottom: -12,
                      left: 0,
                      position: 'absolute',
                    }}>
                    <Line
                      x1="50%"
                      y1="0"
                      x2="50%"
                      y2="100"
                      stroke="#D0D5DD"
                      strokeWidth="2"
                      strokeDasharray="4"
                    />
                  </Svg>
                </>
              </View>
            );

          return (
            <View
              style={{
                alignSelf: 'center',
              }}>
              <BlockComponent
                data={item}
                showLineDown={index !== data.length - 1}
              />
            </View>
          );
        })}
      </View>
    );
  };

  const renderItemParties = (item: any[]) => {
    const newData = groupByOrderAndRole(item);

    return (
      <View
        style={{
          alignItems: 'center',
        }}>
        {newData.map((i, j) => {
          if (!isArray(i))
            return (
              <View
                key={j}
                style={{
                  marginBottom: j !== item.length - 1 ? 24 : 0,
                  zIndex: -1,
                }}>
                <BlockComponent
                  data={i}
                  key={j}
                  showLineDown={j !== item.length - 1}
                />
              </View>
            );
          return renderRowData(i);
        })}
      </View>
    );
  };

  return (
    <ReactNativeZoomableView
      ref={refZoomView}
      maxZoom={30}
      minZoom={0.1}
      bindToBorders={true}
      contentWidth={widthView}>
      <View
        style={{
          alignItems: 'center',
        }}
        onLayout={event => {
          const {width, height} = event.nativeEvent.layout;
          var zoomTo = 1;
          if (width > ScreenWidth) {
            setWidthView(width);
            zoomTo = (ScreenWidth - 40) / Math.round(width);
          }

          if (height > ((ScreenHeight - 230) * 8) / 9) {
            if (((ScreenHeight - 230) * 8) / 9 / height < zoomTo) {
              zoomTo = ((ScreenHeight - 230) * 8) / 9 / height;
            }
          }
          if (refZoomView.current && zoomTo < 1) {
            refZoomView.current.zoomTo(zoomTo);
          }
        }}>
        <StartView />
        {dataRender2.map((item, index) => {
          return (
            <View key={index}>
              <View
                style={[
                  styles.viewStyleCtn,
                  {
                    alignItems: item.some(i => isArray(i))
                      ? 'center'
                      : undefined,
                    backgroundColor: item.some(i => isArray(i))
                      ? 'transparent'
                      : '#F5F5F6',
                    flexDirection: item.some(i => isArray(i))
                      ? 'row'
                      : 'column',
                    padding: item.some(i => isArray(i)) ? 0 : 12,
                    marginVertical: item.some(i => isArray(i)) ? 24 : 0,
                  },
                ]}>
                {item.some(i => isArray(i)) && (
                  <>
                    {/* Gạch ngang trên */}
                    <Svg
                      height="24"
                      width="100%"
                      style={{
                        top: -24,
                        left: (widthRowData?.[0] || 0) / 2 + 12,
                        position: 'absolute',
                      }}>
                      <Line
                        x1="0"
                        y1="2"
                        x2={getWidth()}
                        y2="2"
                        stroke="#D0D5DD"
                        strokeWidth="2"
                        strokeDasharray="4"
                      />
                    </Svg>

                    {/* Gạch ngang dưới */}
                    <Svg
                      height="24"
                      width="100%"
                      style={{
                        bottom: -46,
                        left: (widthRowData?.[0] || 0) / 2 + 12,
                        position: 'absolute',
                      }}>
                      <Line
                        x1="0"
                        y1="2"
                        x2={getWidth()}
                        y2="2"
                        stroke="#D0D5DD"
                        strokeWidth="2"
                        strokeDasharray="4"
                      />
                    </Svg>

                    {/*Dấu cộng dưới */}
                    <View
                      style={{
                        position: 'absolute',
                        bottom: -31,
                        left: 0,
                        right: 0,
                        justifyContent: 'center',
                        alignItems: 'center',
                      }}>
                      <IconGreyCirclePlus width={13} height={13} />
                    </View>
                    {/*Dấu cộng trên */}
                    <View
                      style={{
                        position: 'absolute',
                        top: -31,
                        left: 0,
                        right: 0,
                        justifyContent: 'center',
                        alignItems: 'center',
                      }}>
                      <IconGreyCirclePlus width={13} height={13} />
                    </View>
                  </>
                )}

                {checkPartyId(item)
                  ? renderGroupData(item)
                  : item.every(i => !isArray(i))
                  ? renderItemParties(item)
                  : item.map((i, j) => {
                      return renderRowData(i, j);
                    })}
              </View>
              {index !== dataRender2.length - 1 && (
                <View
                  style={{
                    height: 24,
                  }}>
                  <Svg height="24" width="100%">
                    <Line
                      x1="50%"
                      y1="0"
                      x2="50%"
                      y2="100%"
                      stroke="#D0D5DD"
                      strokeWidth="2"
                      strokeDasharray="4"
                    />
                  </Svg>
                  <View
                    style={{
                      bottom: -4,
                      left: 0,
                      right: 0,
                      position: 'absolute',
                      justifyContent: 'center',
                      alignItems: 'center',
                    }}>
                    <IconGreyDown width={10} height={14} />
                  </View>
                </View>
              )}
            </View>
          );
        })}
        <EndView status={status} />
      </View>
    </ReactNativeZoomableView>
  );
};

export default WorkflowDiagram;

const StartView = () => {
  return (
    <View style={styles.ctbStartView}>
      <View>
        <IconEllipse width={24} height={24} />
        <Svg
          height="24"
          width="100%"
          style={{
            position: 'absolute',
            left: 0,
            top: 24,
          }}>
          <Line
            x1="50%"
            y1="0"
            x2="50%"
            y2="100%"
            stroke="#D0D5DD"
            strokeWidth="2"
            strokeDasharray="4"
          />
        </Svg>
      </View>
    </View>
  );
};

type EndViewType = {
  status: DocumentStatus;
};

const EndView = ({status}: EndViewType) => {
  const renderIcon = () => {
    switch (status) {
      case DocumentStatus.COMPLETED:
        return <IconEllipseSuccess width={24} height={24} />;
      case DocumentStatus.VOIDED:
      case DocumentStatus.REJECTED:
      case DocumentStatus.OVERDUE:
        return <IconEllipseReject width={24} height={24} />;
      default:
        return <IconEllipseInprogress width={24} height={24} />;
    }
  };

  return (
    <View style={styles.ctnEndView}>
      <View>
        <Svg
          height="24"
          width="100%"
          style={{
            position: 'absolute',
            left: 0,
            top: -24,
          }}>
          <Line
            x1="50%"
            y1="0"
            x2="50%"
            y2="100%"
            stroke="#D0D5DD"
            strokeWidth="2"
            strokeDasharray="4"
          />
        </Svg>
        {renderIcon()}
      </View>
      <View
        style={{
          left: 0,
          right: 0,
          top: 12,
          alignItems: 'center',
          position: 'absolute',
        }}>
        <IconGreyDown width={10} height={14} />
      </View>
    </View>
  );
};
