import React, {useState, useCallback} from 'react';
import {
  useWindowDimensions,
  View,
  Modal,
  TouchableOpacity,
  Text,
  ViewStyle,
} from 'react-native';
import {GestureHandlerRootView} from 'react-native-gesture-handler';
import Animated, {
  useSharedValue,
  withSpring,
  useAnimatedStyle,
} from 'react-native-reanimated';
import styles from './styles';

type Props = {
  renderContent: any;
  renderOpenDrawer?: React.JSX.Element;
  container?: ViewStyle;
};

const DrawerCM = ({renderContent, renderOpenDrawer, container}: Props) => {
  const [modalVisible, setModalVisible] = useState(false);
  const {width} = useWindowDimensions();
  const translateX = useSharedValue(-width);

  const openDrawer = useCallback(() => {
    setModalVisible(true);
    translateX.value = withSpring(0, {damping: 15});
  }, []);

  const closeDrawer = useCallback(() => {
    translateX.value = withSpring(-width, {damping: 15});
    setModalVisible(false);
  }, []);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{translateX: translateX.value}],
  }));

  return (
    <GestureHandlerRootView style={[styles.container]}>
      <View style={[container]}>
        {/* Gesture Detector cho phép kéo để mở/đóng */}
        <Modal transparent visible={modalVisible} animationType="fade">
          <Animated.View
            style={[
              styles.drawer,
              animatedStyle,
              {
                width: width,
              },
            ]}>
            {renderContent}
            <TouchableOpacity onPress={closeDrawer} style={styles.closeButton}>
              <Text style={styles.buttonText}>Close</Text>
            </TouchableOpacity>
          </Animated.View>
        </Modal>

        {/* Nút mở Drawer */}
        {renderOpenDrawer ? (
          <TouchableOpacity onPress={openDrawer}>
            {renderOpenDrawer}
          </TouchableOpacity>
        ) : (
          <TouchableOpacity onPress={openDrawer} style={styles.openButton}>
            <Text style={styles.buttonText}>Open Menu</Text>
          </TouchableOpacity>
        )}
      </View>
    </GestureHandlerRootView>
  );
};

export default DrawerCM;
